"func handleAPISkip(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	LogLocal("INFO", "Web Dashboard: Skip current track command triggered")
	RegisterIntentionalSkip()

	reason := r.URL.Query().Get("reason")
	if reason == "" {
		reason = "manual"
	}
	skippedByCatchup := 0
	if reason == "tempo" {
		skippedByCatchup = 1
	}

	if DB != nil {
		_, errDb := DB.Exec(
			"UPDATE play_history SET skipped_by_catchup = $1, skip_reason = $2 WHERE play_status = 'na_ponta'",
			skippedByCatchup, reason,
		)
		if errDb != nil {
			LogLocal("ERROR", "Failed to update play_history on manual skip: %v", errDb)
		}
	}

	client := &http.Client{Timeout: 500 * time.Millisecond}
	resp, err := client.Get("http://127.0.0.1:7000/skip")
	if err != nil {
		http.Error(w, "Failed to skip: "+err.Error(), http.StatusInternalServerError)
		return
	}
	defer resp.Body.Close()

	w.Header().Set("Content-Type", "application/json")
	_, _ = w.Write([]byte(`{"status":"success"}`))
}"

