"package main

import (
	"context"
	"fmt"
	"log"
	"github.com/jackc/pgx/v5/pgxpool"
	"imc-server/internal/database"
	"imc-server/internal/repository"
	"imc-server/internal/utils"
)

func main() {
	dbURL := "postgres://neoroute:@@Mo1isc00@@@localhost:5432/imc_server?sslmode=disable"
	pool, err := pgxpool.New(context.Background(), dbURL)
	if err != nil {
		log.Fatalf("failed to connect: %v", err)
	}
	defer pool.Close()

	database.Pool = pool

	storeRepo := repository.NewStoreRepository()
	stores, err := storeRepo.GetAll(context.Background(), nil)
	if err != nil {
		log.Fatalf("failed to get stores: %v", err)
	}

	for _, s := range stores {
		if s.RadioType == "server" && s.HarborPort != nil {
			fmt.Printf("Recreating container for %s (Harbor Port: %d)...\n", s.StoreName, *s.HarborPort)
			errStart := utils.StartStoreDockerContainer(s)
			if errStart != nil {
				fmt.Printf("FAIL: %v\n", errStart)
			} else {
				fmt.Println("OK")
			}
		}
	}
}
